ValidationRule.errorConditionFormula:
AND((RecordType.DeveloperName = 'Deal_Support_request'),(ISPICKVAL(Type,'Deal Termination')),( ISPICKVAL( Sub_Type__c , 'Corporate Contract') ),  
OR(ISBLANK( End_Date__c ),ISBLANK(Distribution_Email__c),ISBLANK( Reasons_for_Termination__c ),
ISPICKVAL(Eligible_for_SME_Campaigns__c,''), ISPICKVAL(Handover_to_QBR__c,''),AND(ISPICKVAL(Handover_to_QBR__c,'Yes'),ISPICKVAL(Assign_to_QBR_Level__c,''))
) 
)
